from datetime import datetime
from enum import StrEnum

from pydantic import BaseModel, Field

# ── Enums ─────────────────────────────────────────────────────────────────────

class DiscrepancyType(StrEnum):
    MISSING_LEDGER_ENTRY     = "MISSING_LEDGER_ENTRY"
    LEDGER_AMOUNT_MISMATCH   = "LEDGER_AMOUNT_MISMATCH"
    MISSING_BANK_TRANSACTION = "MISSING_BANK_TRANSACTION"
    BANK_AMOUNT_MISMATCH     = "BANK_AMOUNT_MISMATCH"
    MISSING_MERCHANT_RECORD  = "MISSING_MERCHANT_RECORD"
    STATUS_MISMATCH          = "STATUS_MISMATCH"
    DOUBLE_ENTRY             = "DOUBLE_ENTRY"


class Severity(StrEnum):
    LOW      = "LOW"
    MEDIUM   = "MEDIUM"
    HIGH     = "HIGH"
    CRITICAL = "CRITICAL"


class TriggerType(StrEnum):
    MANUAL    = "MANUAL"
    SCHEDULED = "SCHEDULED"


# ── Core models ───────────────────────────────────────────────────────────────

class Discrepancy(BaseModel):
    payment_id  : str
    type        : DiscrepancyType
    severity    : Severity
    layer       : str
    expected    : str | None = None
    actual      : str | None = None
    message     : str
    detected_at : datetime = Field(default_factory=datetime.utcnow)


class PaymentRecord(BaseModel):
    payment_id      : str
    gateway_amount  : int | None = None
    gateway_status  : str | None = None
    ledger_amount   : int | None = None
    ledger_entries  : int           = 0
    bank_amount     : int | None = None
    bank_status     : str | None = None
    merchant_amount : int | None = None
    merchant_status : str | None = None
    is_reconciled   : bool          = False
    discrepancies   : list[Discrepancy] = []


class ReconcileRequest(BaseModel):
    limit       : int                 = 500
    from_date   : str | None       = None
    to_date     : str | None       = None
    payment_ids : list[str] | None = None


class ReconcileResult(BaseModel):
    run_id              : str
    trigger             : TriggerType = TriggerType.MANUAL
    status              : str
    started_at          : datetime
    completed_at        : datetime | None = None
    total_payments      : int = 0
    reconciled          : int = 0
    discrepancies_found : int = 0
    payments            : list[PaymentRecord] = []
    summary             : dict = {}


# ── Schedule models ───────────────────────────────────────────────────────────

class ScheduleConfig(BaseModel):
    enabled  : bool = True
    hour     : int  = 23        # 11 PM
    minute   : int  = 0
    timezone : str  = "America/New_York"
    limit    : int  = 500


class ScheduleStatus(BaseModel):
    enabled          : bool
    next_run         : str | None = None
    last_run         : str | None = None
    last_run_id      : str | None = None
    last_run_status  : str | None = None
    hour             : int
    minute           : int
    timezone         : str
    total_scheduled_runs : int = 0
